import re
from typing import Union

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.exceptions import BadResponse, Timeout

from .telnet import TelnetPdu


class OSP(TelnetPdu):
    POWER_ON_STATUS = "1"
    POWER_OFF_STATUS = "0"

    STATUS_QUERY = "sw{}"
    POWER_SWITCH = "setsw{}{}"
    DEFAULT_PORT = 4001

    def __init__(self, host: str, timeout: Union[float, int] = 10, port: int = DEFAULT_PORT) -> None:
        port = int(port)
        super(OSP, self).__init__(host=host, port=port, timeout=timeout)

    @property
    def _max_ports(self):
        return 8

    def get_port_status(self, port):
        try:
            return super(OSP, self).get_port_status(port)
        except Timeout:
            raise Timeout(
                "Telnet connection timed out or instruction format is incorrect"
            )

    @property
    def _port_setting(self):
        return {
            DeviceStatus.OFF: self.POWER_OFF_STATUS,
            DeviceStatus.ON: self.POWER_ON_STATUS,
        }

    def _build_telnet_command(self, port, status):
        self._verify_port_number(port)
        code_for_status = {
            DeviceStatus.ON: self.POWER_SWITCH.format(port, 1),
            DeviceStatus.OFF: self.POWER_SWITCH.format(port, 0),
            None: self.STATUS_QUERY.format(port),
        }
        return code_for_status[status].encode(self._encoding)

    def _parse_response(self, response):
        if re.match(r"[0-1] [+]?[0-9]*\.?[0-9]+A", response):
            return response.split(" ")[0]
        else:
            raise BadResponse(f"Incorrect status format: {response}")
